/* ======================== */

const photoEl = document.getElementById("photo");
if (photoEl && IMG.photo) { photoEl.addEventListener("load", () => { const i = document.querySelector(".initials"); if (i) i.remove(); }); photoEl.src = IMG.photo; }
const $ = (s, r = document) => r.querySelector(s);
const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt) e.textContent = txt; return e; };
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

// Frappe animée
(function typing() {
  const t = $("#typed"); let r = 0, i = 0, del = false;
  if (reduce) { t.textContent = roles[0]; return; }
  (function tick() {
    const w = roles[r];
    t.textContent = w.slice(0, i);
    if (!del && i === w.length) { del = true; return setTimeout(tick, 1600); }
    if (del && i === 0) { del = false; r = (r + 1) % roles.length; }
    i += del ? -1 : 1;
    setTimeout(tick, del ? 35 : 70);
  })();
})();

// Parcours
timeline.forEach(t => {
  const li = el("li"); const b = el("b", "", t.when + " · " + t.what);
  li.append(b, el("span", "", t.where)); $("#timeline").appendChild(li);
});

// Projets + lightbox
let lbImages = [], lbIndex = 0;
const lb = $("#lightbox"), lbImg = $("#lb-img");
function openLb(imgs, i) { lbImages = imgs; lbIndex = i; showLb(); lb.hidden = false; $(".lb-close").focus(); }
function showLb() {
  lbImg.src = lbImages[lbIndex];
  $(".prev").hidden = $(".next").hidden = lbImages.length < 2;
}
function stepLb(d) { lbIndex = (lbIndex + d + lbImages.length) % lbImages.length; showLb(); }
$(".lb-close").onclick = () => lb.hidden = true;
$(".prev").onclick = () => stepLb(-1);
$(".next").onclick = () => stepLb(1);
lb.addEventListener("click", e => { if (e.target === lb) lb.hidden = true; });
document.addEventListener("keydown", e => {
  if (lb.hidden) return;
  if (e.key === "Escape") lb.hidden = true;
  if (e.key === "ArrowLeft") stepLb(-1);
  if (e.key === "ArrowRight") stepLb(1);
});

function parseVideo(v) {
  const yt = v.match(/(?:youtu\.be\/|v=|embed\/)([\w-]{11})/);
  return yt ? { yt: true, src: "https://www.youtube-nocookie.com/embed/" + yt[1] } : { yt: false, src: v };
}
projects.forEach(p => {
  const art = el("article", "project" + (p.mobile ? " is-mobile" : ""));
  const head = el("div", "p-head"); head.appendChild(el("h3", "", p.title));
  const tags = el("ul", "tags"); p.tech.forEach(t => tags.appendChild(el("li", "", t))); head.appendChild(tags);
  art.append(head, el("p", "p-lead", p.text));

  // 1. Le README, visible directement
  if (p.features || p.install || p.link || (p.images && p.images.length)) {
    const body = el("div", "p-body"), readme = el("div", "p-readme");
    if (p.features) {
      readme.appendChild(el("h4", "", "Fonctionnalités"));
      const f = el("ul", "feat"); p.features.forEach(x => f.appendChild(el("li", "", x))); readme.appendChild(f);
    }
    if (p.install) {
      const d = el("details", "install"); d.appendChild(el("summary", "", "Installation"));
      const pre = el("pre"); pre.appendChild(el("code", "", p.install)); d.appendChild(pre); readme.appendChild(d);
    }
    if (p.link) {
      const a = el("a", "btn-link", "Voir le code sur GitHub"); a.href = p.link; a.target = "_blank"; a.rel = "noopener"; readme.appendChild(a);
    }
    body.appendChild(readme);
    if (p.images && p.images.length) {
      const g = el("div", "shots");
      p.images.forEach((src, i) => {
        const b = el("button", "shot-btn"); b.type = "button"; b.setAttribute("aria-label", "Agrandir la capture " + (i + 1));
        const im = el("img"); im.src = src; im.alt = "Capture " + (i + 1) + " de " + p.title; im.loading = "lazy";
        b.appendChild(im); b.onclick = () => openLb(p.images, i); g.appendChild(b);
      });
      body.appendChild(g);
    }
    art.appendChild(body);
  }

  // 2. La partie vidéo, après le README
  if (p.video) {
    const v = parseVideo(p.video), box = el("div", "p-video");
    box.appendChild(el("h4", "", p.videoTitle || "Démonstration vidéo"));
    const frame = el("div", "vframe" + (p.portraitVideo ? " portrait" : ""));
    if (v.yt) {
      const f = el("iframe"); f.src = v.src; f.title = "Vidéo : " + p.title; f.loading = "lazy";
      f.allow = "encrypted-media; picture-in-picture; fullscreen"; f.allowFullscreen = true; frame.appendChild(f);
    } else {
      const vid = el("video"); vid.controls = true; vid.preload = "metadata"; vid.playsInline = true; vid.src = v.src;
      vid.addEventListener("error", () => box.remove()); frame.appendChild(vid);
    }
    box.appendChild(frame); art.appendChild(box);
  }
  $("#projects").appendChild(art);
});

// Projecteur lumineux qui suit la souris sur les cartes
document.querySelectorAll(".card").forEach(card => card.addEventListener("pointermove", e => {
  const r = card.getBoundingClientRect();
  card.style.setProperty("--mx", (e.clientX - r.left) + "px"); card.style.setProperty("--my", (e.clientY - r.top) + "px");
}));

// Compétences (logos animés)
function logo(spec) {
  const ns = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(ns, "svg"); svg.setAttribute("viewBox", "0 0 24 24"); svg.setAttribute("aria-hidden", "true");
  if (spec === "ui") {
    svg.setAttribute("fill", "none"); svg.setAttribute("stroke", "#8A5530"); svg.setAttribute("stroke-width", "1.8"); svg.setAttribute("stroke-linejoin", "round"); svg.setAttribute("stroke-linecap", "round");
    svg.innerHTML = '<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 9h18M9 9v11"/><circle cx="6" cy="6.5" r=".6" fill="#8A5530"/>';
  } else if (spec === "network") {
    svg.setAttribute("fill", "none"); svg.setAttribute("stroke", "#6B3A1E"); svg.setAttribute("stroke-width", "1.8"); svg.setAttribute("stroke-linecap", "round");
    svg.innerHTML = '<circle cx="12" cy="5" r="2.2"/><circle cx="5" cy="18" r="2.2"/><circle cx="19" cy="18" r="2.2"/><path d="M12 7.2v4.3M12 11.5L6.3 16M12 11.5l5.7 4.5"/>';
  } else if (typeof spec === "object") {
    svg.innerHTML = '<rect x="2" y="2" width="20" height="20" rx="5" fill="#' + spec.hex + '"/><text x="12" y="16.6" text-anchor="middle" font-family="Sora,sans-serif" font-weight="800" font-size="13" fill="#fff">' + spec.letter + '</text>';
  } else {
    const p = document.createElementNS(ns, "path"); p.setAttribute("d", ICONS[spec].path); p.setAttribute("fill", "#" + ICONS[spec].hex);
    svg.appendChild(p);
  }
  return svg;
}
let n = 0;
Object.entries(skills).forEach(([g, list]) => {
  const box = el("div"); box.appendChild(el("h3", "", g));
  const ul = el("ul", "logos");
  list.forEach(([name, spec, note]) => {
    const li = el("li"); li.style.setProperty("--d", (n++ % 7) * 0.35 + "s");
    const badge = el("span", "badge"); badge.appendChild(logo(spec));
    li.append(badge, el("span", "", name)); if (note) li.appendChild(el("span", "note", note)); ul.appendChild(li);
  });
  box.appendChild(ul); $("#skills").appendChild(box);
});

// Effet de profondeur au mouvement de la souris
const stage = $("#stage");
if (stage && !reduce && matchMedia("(hover: hover)").matches) {
  addEventListener("mousemove", e => {
    const x = e.clientX / innerWidth - .5, y = e.clientY / innerHeight - .5;
    stage.querySelectorAll(".depth").forEach(d => { const k = +d.dataset.depth; d.style.transform = "translate(" + (-x * k) + "px," + (-y * k) + "px)"; });
  }, { passive: true });
}

// Étiquettes façon outil de design sur chaque section
const names = { apropos: "À propos", parcours: "Parcours", projets: "Projets", competences: "Compétences", contact: "Contact" };
document.querySelectorAll(".block").forEach((sec, i) => {
  const h2 = sec.querySelector("h2");
  if (h2 && names[sec.id]) sec.insertBefore(el("span", "frame-label", "Frame " + (i + 2) + " · " + names[sec.id]), h2);
});
// Apparition échelonnée des éléments de chaque section
[".about p", ".panel", ".timeline li", ".project", ".skill-groups > div", ".links li"].forEach(sel =>
  document.querySelectorAll(sel).forEach((n, i) => { n.classList.add("stag"); n.style.setProperty("--i", i); }));

// Apparition au défilement
const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } }), { threshold: .12 });
document.querySelectorAll(".reveal").forEach(s => io.observe(s));

// Barre de progression + lien actif
const bar = $(".progress"), links = [...document.querySelectorAll("nav a")];
const secs = links.map(a => $(a.getAttribute("href")));
addEventListener("scroll", () => {
  const h = document.documentElement;
  document.querySelector(".top").classList.toggle("scrolled", scrollY > 20);
  bar.style.width = (h.scrollTop / (h.scrollHeight - h.clientHeight) * 100) + "%";
  const y = scrollY + 120;
  links.forEach((a, i) => a.classList.toggle("active", secs[i].offsetTop <= y && secs[i].offsetTop + secs[i].offsetHeight > y));
}, { passive: true });

// Thème clair / sombre
const root = document.documentElement;
const saved = (() => { try { return localStorage.getItem("theme"); } catch { return null; } })();
root.dataset.theme = saved || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
$("#theme").onclick = () => {
  root.dataset.theme = root.dataset.theme === "dark" ? "light" : "dark";
  try { localStorage.setItem("theme", root.dataset.theme); } catch {}
};

// Menu mobile
const burger = $(".burger"), menu = $("#menu");
burger.onclick = () => { const o = menu.classList.toggle("open"); burger.setAttribute("aria-expanded", o); };
menu.onclick = () => { menu.classList.remove("open"); burger.setAttribute("aria-expanded", false); };

$("#year").textContent = new Date().getFullYear();


// Curseur animé de la scène d'ouverture
(function stageCursor() {
  const cur = $(".cursor"), st = $("#stage");
  if (!cur || !st || reduce) return;
  const pill = $(".pill"), toggle = $(".toggle"), art = $(".artboard");
  const go = (node, fx, fy) => {
    const s = st.getBoundingClientRect(), r = node.getBoundingClientRect();
    cur.style.transform = "translate(" + (r.left - s.left + r.width * fx) + "px," + (r.top - s.top + r.height * fy) + "px)";
  };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  go(art, .62, .42);
  (async function loop() {
    await sleep(2800);
    for (;;) {
      if (document.hidden) { await sleep(1000); continue; }
      go(art, .7, .35); await sleep(1600);
      go(pill, .3, .9); await sleep(1300); pill.classList.add("pressed"); await sleep(200); pill.classList.remove("pressed");
      toggle.classList.add("on"); await sleep(1800); toggle.classList.remove("on");
      go(art, .25, .6); await sleep(1600);
    }
  })();
  addEventListener("resize", () => go(art, .62, .42));
})();
